render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#ecg-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const bpm = params.bpm || 75;
const ampMult = params.amplitude !== undefined ? params.amplitude : 1.0;
const vertOffset = params.vertical_offset || 0;
const textPosX = params.text_x !== undefined ? params.text_x : 20;
const textPosY = params.text_y !== undefined ? params.text_y : 35;
const fontSize = params.font_size || 18;

const showBorder = params.show_border !== false;
const showGrid = params.show_grid !== false;
const lineColor = params.line_color || '#00FF66';
const bgColor = params.bg_color || '#080E0A';
const lineWidth = params.line_width || 2.5;
const sweepSpeed = (params.sweep_speed || 1.0) * 170;

// Margen según si el borde está activo
const pad = showBorder ? Math.min(width, height) * 0.05 : 0;
const screenX = pad;
const screenY = pad;
const screenW = width - pad * 2;
const screenH = height - pad * 2;

// Fondo y Marco Outer
c.fillStyle = bgColor;
if (showBorder) {
  c.fillStyle = '#121614';
  c.fillRect(0, 0, width, height);

  c.save();
  c.fillStyle = bgColor;
  c.strokeStyle = '#25332B';
  c.lineWidth = 4;
  c.beginPath();
  c.roundRect(screenX, screenY, screenW, screenH, 10);
  c.fill();
  c.stroke();
  c.restore();
} else {
  c.fillRect(0, 0, width, height);
}

c.save();
c.beginPath();
c.rect(screenX, screenY, screenW, screenH);
c.clip();

// 1. Cuadrícula médica
if (showGrid) {
  c.strokeStyle = lineColor;
  c.lineWidth = 1;
  const gridStep = 18 * Math.min(width, height) / 400;

  // Cuadrícula fina
  c.globalAlpha = 0.06;
  c.beginPath();
  for (let x = screenX; x <= screenX + screenW; x += gridStep) {
    c.moveTo(x, screenY);
    c.lineTo(x, screenY + screenH);
  }
  for (let y = screenY; y <= screenY + screenH; y += gridStep) {
    c.moveTo(screenX, y);
    c.lineTo(screenX + screenW, y);
  }
  c.stroke();

  // Cuadrícula principal (cada 5 celdas)
  c.globalAlpha = 0.14;
  c.lineWidth = 1.2;
  c.beginPath();
  for (let x = screenX; x <= screenX + screenW; x += gridStep * 5) {
    c.moveTo(x, screenY);
    c.lineTo(x, screenY + screenH);
  }
  for (let y = screenY; y <= screenY + screenH; y += gridStep * 5) {
    c.moveTo(screenX, y);
    c.lineTo(screenX + screenW, y);
  }
  c.stroke();
  c.globalAlpha = 1.0;
}

// 2. Función de onda fisiológica ECG (P, Q, R, S, T)
const beatDuration = 60 / bpm;
const cursorRelX = (time * sweepSpeed) % screenW;
const cursorX = screenX + cursorRelX;
const centerY = screenY + screenH / 2 + vertOffset;
const maxAmp = (screenH * 0.35) * ampMult;

function getECGSample(t) {
  const p = ((t % beatDuration) + beatDuration) % beatDuration / beatDuration;
  if (p < 0.12) {
    return Math.sin((p / 0.12) * Math.PI) * 0.12;
  } else if (p < 0.18) {
    return 0;
  } else if (p < 0.21) {
    return -0.15 * Math.sin(((p - 0.18) / 0.03) * Math.PI);
  } else if (p < 0.26) {
    return 1.0 * Math.sin(((p - 0.21) / 0.05) * Math.PI);
  } else if (p < 0.31) {
    return -0.32 * Math.sin(((p - 0.26) / 0.05) * Math.PI);
  } else if (p < 0.40) {
    return 0;
  } else if (p < 0.60) {
    return 0.22 * Math.sin(((p - 0.40) / 0.20) * Math.PI);
  }
  return 0;
}

// 3. Dibujado de la estela del haz de luz (Sweep Trace)
const gapWidth = 40;
const step = 2;
let prevX = null;
let prevY = null;

for (let x = screenX; x <= screenX + screenW; x += step) {
  const relX = x - screenX;
  let distBehind = cursorRelX - relX;
  if (distBehind < 0) distBehind += screenW;

  if (distBehind > screenW - gapWidth) {
    prevX = null;
    prevY = null;
    continue;
  }

  const timeAtX = time - (distBehind / sweepSpeed);
  const ecgVal = getECGSample(timeAtX);
  const y = centerY - ecgVal * maxAmp;

  const alpha = Math.max(0, 1 - (distBehind / (screenW - gapWidth)));

  if (prevX !== null) {
    c.strokeStyle = lineColor;
    c.lineWidth = lineWidth;
    c.lineCap = 'round';
    c.globalAlpha = alpha;
    c.shadowColor = lineColor;
    c.shadowBlur = 8 * alpha;

    c.beginPath();
    c.moveTo(prevX, prevY);
    c.lineTo(x, y);
    c.stroke();
  }

  prevX = x;
  prevY = y;
}

// 4. Punto del cabezal principal de lectura
const currentECG = getECGSample(time);
const cursorY = centerY - currentECG * maxAmp;

c.save();
c.globalAlpha = 1.0;
c.fillStyle = '#FFFFFF';
c.shadowColor = lineColor;
c.shadowBlur = 14;
c.beginPath();
c.arc(cursorX, cursorY, lineWidth * 1.4, 0, Math.PI * 2);
c.fill();
c.restore();

// 5. Lectura HUD (Frecuencia en pantalla + Latido)
c.globalAlpha = 0.9;
c.fillStyle = lineColor;
c.font = `bold ${fontSize}px monospace`;
c.textAlign = 'left';
c.textBaseline = 'top';

const drawX = screenX + textPosX;
const drawY = screenY + textPosY;
const bpmText = `HR: ${Math.round(bpm)} BPM`;

c.fillText(bpmText, drawX, drawY);

// Indicador visual de 'Beep' en el pico R
const currentPhase = ((time % beatDuration) + beatDuration) % beatDuration / beatDuration;
if (currentPhase >= 0.21 && currentPhase <= 0.27) {
  c.fillStyle = '#FF3344';
  c.shadowColor = '#FF3344';
  c.shadowBlur = 12;
  c.font = `bold ${fontSize}px sans-serif`;
  const textWidth = c.measureText(bpmText).width;
  c.fillText('♥', drawX + textWidth + 8, drawY);
}

c.restore();
